INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260031','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260031","revision":1,"targetId":"80000000-0000-4000-8000-000000012603","prompt":"In der zweiten Mahnung setzt der Anbieter eine letzte Zahlungsfrist. Was will er erreichen?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"A deadline for payment is central.","de":"Eine Zahlungsfrist betrifft eine noch offene Forderung."},"options":[{"id":"0","text":"Die offene Rechnung soll bezahlt werden."},{"id":"1","text":"Die Ware soll kostenlos zurückgeschickt werden."},{"id":"2","text":"Die Stelle soll neu besetzt werden."},{"id":"3","text":"Die Bestellung soll vergrößert werden."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The supplier is asking for payment.","de":"Der Anbieter verlangt die Begleichung der Rechnung."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"In der zweiten Mahnung fordert der Anbieter erneut die Zahlung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1490 (85211fb6083dd12d3311f0904ed24e42f9b57545a8b1327e56c62fc12ba33cd8), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
