INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260081','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260081","revision":1,"targetId":"80000000-0000-4000-8000-000000012608","prompt":"Wegen eines Mangels an Fachkräften bleiben drei Stellen unbesetzt. Was ist das Problem?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The construction „Mangel an“ expresses insufficiency.","de":"„Mangel an“ bedeutet, dass etwas nicht ausreichend vorhanden ist."},"options":[{"id":"0","text":"Es gibt zu wenige qualifizierte Arbeitskräfte."},{"id":"1","text":"Es gibt zu viele neue Mitarbeitende."},{"id":"2","text":"Alle Stellen sind bereits besetzt."},{"id":"3","text":"Die Löhne wurden gerade erhöht."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"There is a shortage of skilled workers.","de":"Es fehlen qualifizierte Arbeitskräfte."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Drei Stellen bleiben wegen fehlender Fachkräfte unbesetzt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1498 (a23ca5a52d0309ad29a4179e7e3f0ab67e8029f01a6800770ad1fa258ed54d3d), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
