INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260091','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260091","revision":1,"targetId":"80000000-0000-4000-8000-000000012609","prompt":"Nach der Reparatur der undichten Leitungen dokumentiert die Firma die Mängelbeseitigung. Was wurde erledigt?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Leaking pipes were repaired.","de":"Undichte Leitungen wurden repariert."},"options":[{"id":"0","text":"Die festgestellten Defekte wurden behoben."},{"id":"1","text":"Ein neuer Mietvertrag wurde geschlossen."},{"id":"2","text":"Die Materialpreise wurden erhöht."},{"id":"3","text":"Ein Wartungsvertrag wurde gekündigt."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The documented work was the remedying of faults.","de":"Dokumentiert wurde die Behebung der Mängel."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Reparatur dokumentiert die Firma, dass die Mängel behoben wurden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1499 (1fb6a337d26947e3493111ea429bccb48269a4179b364260eaeb99227278bc13), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
