INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260141','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260141","revision":1,"targetId":"80000000-0000-4000-8000-000000012614","prompt":"Auf der Verpackung steht die Marke des Herstellers. Welche Information liefert sie?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"A brand identifies a producer or product line.","de":"Eine Marke hilft bei der Wiedererkennung eines Herstellers."},"options":[{"id":"0","text":"Von welcher Firma das Produkt stammt"},{"id":"1","text":"Wie schwer die Verpackung ist"},{"id":"2","text":"Wann das Produkt abläuft"},{"id":"3","text":"Wie hoch die Mehrwertsteuer ist"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"It identifies the product''s brand or company.","de":"Die Marke kennzeichnet den Hersteller oder das Produkt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Marke auf der Verpackung zeigt, zu welcher Firma das Produkt gehört.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1507 (ef4dd0f81d48c05a06a6dc6e0dd9258b8d0694098c25069d850f1e1bc362a46f), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
