INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260150','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260150","revision":1,"targetId":"80000000-0000-4000-8000-000000012615","prompt":"Das ___ plant eine Werbekampagne, um neue Kundinnen und Kunden zu erreichen.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The task is to attract customers through advertising.","de":"Die Abteilung möchte mit Werbung neue Kundschaft gewinnen."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Marketing"},{"id":"1","text":"Lager"},{"id":"2","text":"Controlling"},{"id":"3","text":"Personalbüro"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Marketing plans activities to promote products.","de":"Marketing umfasst Maßnahmen zur Vermarktung von Produkten und Dienstleistungen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Marketing plant eine Werbekampagne, um neue Kundinnen und Kunden zu erreichen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1508 (a1d44af19855cf4d0a1dbbd62410bf85a480cc05a572ac6a3b57c3c3df81460e), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
