INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260151','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260151","revision":1,"targetId":"80000000-0000-4000-8000-000000012615","prompt":"Für das Marketing testet das Team zwei Werbebotschaften mit einer Zielgruppe. Welchem Zweck dient die Arbeit?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The team is testing advertising messages.","de":"Das Team prüft, wie Werbung bei einer Zielgruppe ankommt."},"options":[{"id":"0","text":"Produkte bei Kundinnen und Kunden bekannt machen"},{"id":"1","text":"Maschinen regelmäßig warten"},{"id":"2","text":"Lohnsteuer für Beschäftigte berechnen"},{"id":"3","text":"Ersatzteile an Werkstätten ausliefern"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The work supports product promotion.","de":"Die Arbeit dient dazu, Produkte oder Dienstleistungen zu vermarkten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Team prüft Werbebotschaften, um Produkte besser zu vermarkten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1508 (a1d44af19855cf4d0a1dbbd62410bf85a480cc05a572ac6a3b57c3c3df81460e), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
