INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260160','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260160","revision":1,"targetId":"80000000-0000-4000-8000-000000012616","prompt":"Vor der Einführung des Produkts führt die Firma eine ___ durch, um Kundenwünsche zu ermitteln.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The company wants evidence about customer needs.","de":"Das Unternehmen untersucht die Nachfrage."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Marktuntersuchung"},{"id":"1","text":"Inventur"},{"id":"2","text":"Reparatur"},{"id":"3","text":"Betriebsfeier"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Marktuntersuchung examines a market and its customers.","de":"Eine Marktuntersuchung analysiert den Markt und die Nachfrage."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Vor der Einführung des Produkts führt die Firma eine Marktuntersuchung durch, um Kundenwünsche zu ermitteln.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1510 (d35afd40b3e4fc96fcc9856b3a1fd8ed08ab63a7a36043da579b2aac255e2030), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
