INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001270011','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001270011","revision":1,"targetId":"80000000-0000-4000-8000-000000012701","prompt":"Die Tischplatte besteht aus einem recycelten Material. Was bezeichnet „Material“ hier?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The table top is made of something.","de":"Die Tischplatte wird aus einem bestimmten Stoff gefertigt."},"options":[{"id":"0","text":"Den Stoff, aus dem die Platte hergestellt ist"},{"id":"1","text":"Den Preis für den Transport"},{"id":"2","text":"Den Vertrag mit dem Händler"},{"id":"3","text":"Die Lieferadresse der Möbel"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Material refers to the substance of the table top.","de":"Gemeint ist der Werkstoff der Tischplatte."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Tischplatte wurde aus einem recycelten Werkstoff hergestellt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1517 (105e94c2ba6ff035e20287626e0607b24f31d492da4e351f732ce06d4058ade2), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
