INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001270071','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001270071","revision":1,"targetId":"80000000-0000-4000-8000-000000012707","prompt":"Seine Meckerei über jeden kleinen Fehler nervt die Kolleginnen. Wie ist „Meckerei“ hier gemeint?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The tone is negative and repetitive.","de":"Das Wort beschreibt ein wiederholtes, negatives Verhalten."},"options":[{"id":"0","text":"Als ständiges, kleinliches Beschweren"},{"id":"1","text":"Als sachliche schriftliche Fehleranalyse"},{"id":"2","text":"Als freundliches Lob für die Arbeit"},{"id":"3","text":"Als verbindliche Arbeitsanweisung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The term criticizes persistent petty complaints.","de":"Gemeint ist ständiges, oft kleinliches Nörgeln."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Kolleginnen ärgern sich über sein ständiges Nörgeln.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1523 (204bace4571caabdb0500fb240253ea75a4b8543b2eef16d26e877a9b0f6c517), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
