INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001270080','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001270080","revision":1,"targetId":"80000000-0000-4000-8000-000000012708","prompt":"Das Krankenhaus organisiert die ___ neu, damit wichtige Arzneimittel nicht ausgehen.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The hospital must keep necessary drugs available.","de":"Benötigte Arzneimittel sollen immer vorhanden sein."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Medikamentenversorgung"},{"id":"1","text":"Personalabrechnung"},{"id":"2","text":"Mülltrennung"},{"id":"3","text":"Gebäudereinigung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Medikamentenversorgung means providing medicines.","de":"Medikamentenversorgung ist die Bereitstellung benötigter Arzneimittel."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Das Krankenhaus organisiert die Medikamentenversorgung neu, damit wichtige Arzneimittel nicht ausgehen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1525 (8625bb47f7bc7ac32045083a23cf81e303b313df54d8c6ed1f0867cfedcaba7c), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
