INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001270081','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001270081","revision":1,"targetId":"80000000-0000-4000-8000-000000012708","prompt":"Trotz Lieferengpässen ist die Medikamentenversorgung der Station gesichert. Was bedeutet das?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Supply problems have not stopped access to medicines.","de":"Trotz Problemen bei Lieferungen sind Arzneimittel vorhanden."},"options":[{"id":"0","text":"Die benötigten Arzneimittel sind verfügbar."},{"id":"1","text":"Die Station hat keine Patientinnen und Patienten."},{"id":"2","text":"Alle Operationen wurden verschoben."},{"id":"3","text":"Das Personal wurde neu eingeteilt."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The ward can obtain the medicines it needs.","de":"Die Versorgung mit den benötigten Medikamenten funktioniert."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Auf der Station sind die nötigen Arzneimittel verfügbar.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1525 (8625bb47f7bc7ac32045083a23cf81e303b313df54d8c6ed1f0867cfedcaba7c), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
