INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001270151','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001270151","revision":1,"targetId":"80000000-0000-4000-8000-000000012715","prompt":"Trotz ihrer Meinungsverschiedenheit arbeiteten beide weiter zusammen. Was war zwischen ihnen passiert?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"They disagreed but continued collaborating.","de":"Sie waren nicht einer Meinung, arbeiteten aber weiter."},"options":[{"id":"0","text":"Sie waren in einer Frage unterschiedlicher Ansicht."},{"id":"1","text":"Sie hatten in allen Punkten dieselbe Meinung."},{"id":"2","text":"Sie hatten den Vertrag bereits unterschrieben."},{"id":"3","text":"Sie hatten ihre Arbeitsplätze getauscht."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"They held different opinions.","de":"Die beiden waren in einer Frage uneinig."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Obwohl sie unterschiedlicher Meinung waren, arbeiteten sie zusammen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1534 (81ecb2f8fd7881a9da7d685bbf91dc160d92b4365a4d472351fd1734ce5e8f65), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
