INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280021','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280021","revision":1,"targetId":"80000000-0000-4000-8000-000000012802","prompt":"Die Messmethode nutzt Licht, um die Konzentration einer Lösung zu bestimmen. Was bezeichnet das Wort?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Focus on how the value is determined.","de":"Achte darauf, wie der Wert ermittelt wird."},"options":[{"id":"0","text":"Das Verfahren, mit dem gemessen wird"},{"id":"1","text":"Den Preis des Messgeräts"},{"id":"2","text":"Die Farbe der Laborwand"},{"id":"3","text":"Die Anzahl der Mitarbeitenden"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"It names the measuring method.","de":"Gemeint ist das Messverfahren."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Mit dieser Messmethode wird die Konzentration mithilfe von Licht bestimmt.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1545 (9d268391fe4e1270bbd5fbdae8e2e624b68f90e64f476e792daeb4c5c6167785), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
