INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280051','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280051","revision":1,"targetId":"80000000-0000-4000-8000-000000012805","prompt":"Kupfer ist ein Metall und wird häufig für Kabel verwendet. Warum eignet es sich?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Copper is used as a conductor.","de":"Kupfer wird als elektrischer Leiter verwendet."},"options":[{"id":"0","text":"Es leitet elektrischen Strom gut."},{"id":"1","text":"Es ist ein besonders weicher Stoff."},{"id":"2","text":"Es besteht aus gepresstem Papier."},{"id":"3","text":"Es löst sich sofort in Wasser auf."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Copper conducts electricity.","de":"Kupfer ist ein gut leitendes Metall."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Kupfer eignet sich für Kabel, weil es Strom gut leitet.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1548 (92496be95926d4fb60ad1d03d9da04e09bbeba3d5d97c8749a97e53e17978b36), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
