INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280070','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280070","revision":1,"targetId":"80000000-0000-4000-8000-000000012807","prompt":"Mit mehreren Millionen Einwohnern und großer internationaler Bedeutung gilt die Stadt als ___.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The city is a large international centre.","de":"Die Stadt ist groß und international bedeutend."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Metropole"},{"id":"1","text":"Dorf"},{"id":"2","text":"Vorort"},{"id":"3","text":"Werkstatt"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Metropole means a major city.","de":"Eine Metropole ist eine große, bedeutende Stadt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Mit mehreren Millionen Einwohnern und großer internationaler Bedeutung gilt die Stadt als Metropole.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1551 (8aff5a54c084e61a79c72fece4be922a904c667b2414f5735a03c55d8e90b7e4), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
