INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280120','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280120","revision":1,"targetId":"80000000-0000-4000-8000-000000012812","prompt":"Weil er seit drei Monaten keine Miete bezahlt hat, hat er hohe ___.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"Several rent payments remain unpaid.","de":"Mehrere Monatsmieten wurden nicht bezahlt."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Mietschulden"},{"id":"1","text":"Mieteinnahmen"},{"id":"2","text":"Rabatte"},{"id":"3","text":"Provisionen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Mietschulden are unpaid rent amounts.","de":"Mietschulden sind noch offene Mietzahlungen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Weil er seit drei Monaten keine Miete bezahlt hat, hat er hohe Mietschulden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1557 (90f35c2916b469a729d19c0c4e1de15d88aedf805ea7ca7ef9ec0e325b430d75), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
