INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280121','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280121","revision":1,"targetId":"80000000-0000-4000-8000-000000012812","prompt":"Die Mieterin vereinbart eine Ratenzahlung für ihre Mietschulden. Was möchte sie begleichen?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Installments help pay an existing debt.","de":"In Raten soll eine bestehende Schuld bezahlt werden."},"options":[{"id":"0","text":"Noch offene Mietbeträge"},{"id":"1","text":"Bereits bezahlte Stromrechnungen"},{"id":"2","text":"Eine neue Kaution für ein Auto"},{"id":"3","text":"Die Kosten eines Urlaubs"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"She is paying rent arrears.","de":"Sie möchte ausstehende Mietzahlungen begleichen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Mieterin zahlt ihre offenen Mietschulden in Raten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1557 (90f35c2916b469a729d19c0c4e1de15d88aedf805ea7ca7ef9ec0e325b430d75), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
