INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280140','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280140","revision":1,"targetId":"80000000-0000-4000-8000-000000012814","prompt":"Die ___ ist vor fünf Jahren aus einem anderen Land zugezogen und lebt seitdem hier.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"She moved from another country to live here.","de":"Sie ist dauerhaft aus einem anderen Land zugezogen."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Migrantin"},{"id":"1","text":"Touristin"},{"id":"2","text":"Pendlerin"},{"id":"3","text":"Vermieterin"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Migrantin is a woman who has migrated.","de":"Eine Migrantin ist eine Frau, die in eine andere Region oder ein anderes Land gezogen ist."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Migrantin ist vor fünf Jahren aus einem anderen Land zugezogen und lebt seitdem hier.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1559 (52ff216b09eed52cf45dfe5cd6ee7a8648bbbbd6b080540b944d98bfee03ea19), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
