INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280141','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280141","revision":1,"targetId":"80000000-0000-4000-8000-000000012814","prompt":"Als Migrantin erzählt sie von ihrem Umzug in ein anderes Land. Was beschreibt das Wort?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The word refers to a move, not a legal status.","de":"Es geht um einen Wohnortwechsel, nicht um einen bestimmten Rechtsstatus."},"options":[{"id":"0","text":"Eine Frau, die ihren Wohnort über eine Grenze verlegt hat"},{"id":"1","text":"Eine Frau, die nur einen Tagesausflug macht"},{"id":"2","text":"Eine Frau, die eine Wohnung vermietet"},{"id":"3","text":"Eine Frau, die ein Geschäft gegründet hat"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"She has migrated to another country.","de":"Sie ist in ein anderes Land umgezogen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Migrantin berichtet über ihren Wohnortwechsel in ein anderes Land.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1559 (52ff216b09eed52cf45dfe5cd6ee7a8648bbbbd6b080540b944d98bfee03ea19), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
