INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280151','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280151","revision":1,"targetId":"80000000-0000-4000-8000-000000012815","prompt":"Die Studie untersucht Migration zwischen verschiedenen Ländern. Worum geht es?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The study concerns where people live.","de":"Die Studie betrachtet Wohnortwechsel zwischen Ländern."},"options":[{"id":"0","text":"Um den Umzug von Menschen über Landesgrenzen"},{"id":"1","text":"Um die Reparatur internationaler Züge"},{"id":"2","text":"Um den Versand von Waren per Post"},{"id":"3","text":"Um die Erfassung von Lagerbeständen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"It examines cross-border human migration.","de":"Untersucht werden grenzüberschreitende Wohnortwechsel von Menschen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Studie untersucht, wie Menschen von einem Land in ein anderes ziehen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1560 (437cb4a46f1aaed5086beeb6519a675aa326d6f5c505c2ea292a22b5f8308560), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
