INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001280171','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001280171","revision":1,"targetId":"80000000-0000-4000-8000-000000012817","prompt":"Für die erfasste Beschäftigung darf der Arbeitgeber den gesetzlichen Mindestlohn nicht unterschreiten. Was bedeutet das?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The rule sets a lower boundary, not identical pay.","de":"Die Regel nennt eine Untergrenze, keinen einheitlichen Lohn für alle."},"options":[{"id":"0","text":"Er muss mindestens die festgelegte Lohnuntergrenze zahlen."},{"id":"1","text":"Er muss jeder Person dasselbe Gehalt zahlen."},{"id":"2","text":"Er darf grundsätzlich keinen Stundenlohn vereinbaren."},{"id":"3","text":"Er muss alle Beschäftigten monatlich befördern."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The employer must respect the wage floor.","de":"Der Arbeitgeber muss die geltende Lohnuntergrenze einhalten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Arbeitgeber muss mindestens den gesetzlich vorgesehenen Lohn zahlen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1565 (e8fe663a0454a4340b6a80e869b9570f17858904c71276b120d69d1db7cc80e1), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
