INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001290001','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001290001","revision":1,"targetId":"80000000-0000-4000-8000-000000012900","prompt":"Ohne die Mitarbeit aller Teammitglieder wäre der Bericht nicht fertig geworden. Was war entscheidend?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The team contributed to finishing the report.","de":"Das Team hat gemeinsam am Bericht gearbeitet."},"options":[{"id":"0","text":"Die aktive Beteiligung des Teams"},{"id":"1","text":"Die Zahl der Urlaubstage"},{"id":"2","text":"Die Höhe der Mietkosten"},{"id":"3","text":"Die neue Büroeinrichtung"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The team''s collaboration was essential.","de":"Die gemeinsame Mitarbeit war entscheidend."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Dank der Mitarbeit aller Teammitglieder wurde der Bericht fertig.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1570 (520d7d8ad4872f8d7eca76e04308fe820babae2b2e26e2532b7574eae9d18b92), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
