INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001290031','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001290031","revision":1,"targetId":"80000000-0000-4000-8000-000000012903","prompt":"Bei der Mitbestimmung werden Beschäftigte an bestimmten betrieblichen Entscheidungen beteiligt. Was ist damit gemeint?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The concept concerns having a say.","de":"Es geht um die Beteiligung an Entscheidungen."},"options":[{"id":"0","text":"Beteiligung an Entscheidungen"},{"id":"1","text":"Ausschluss aller Beschäftigten"},{"id":"2","text":"Automatische Beförderung aller Mitarbeitenden"},{"id":"3","text":"Verkauf von Firmenanteilen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"It means taking part in decision-making.","de":"Mitbestimmung ermöglicht Beteiligung an bestimmten Entscheidungen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Beschäftigten können bei bestimmten Entscheidungen mitbestimmen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1574 (0256641ee6a2f65a968007f8112035d26b5b9fb3d2bef9e976ed62735b529065), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
