INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001290080','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001290080","revision":1,"targetId":"80000000-0000-4000-8000-000000012908","prompt":"Die Auszubildenden wünschen sich mehr ___ bei der Gestaltung des Ausbildungsplans.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"They want to express views on the training plan.","de":"Sie möchten bei der Planung ihre Meinung einbringen."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Mitspracherecht"},{"id":"1","text":"Parkraum"},{"id":"2","text":"Fahrgeld"},{"id":"3","text":"Lagerbestand"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Mitspracherecht means having a voice in decisions.","de":"Mitspracherecht ist das Recht, bei Entscheidungen mitzureden."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Auszubildenden wünschen sich mehr Mitspracherecht bei der Gestaltung des Ausbildungsplans.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1579 (3b33052e144c4a3a831f1871a467e42bfa8a6c5ef031565d17a2bc9f547fb153), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
