INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001290081','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001290081","revision":1,"targetId":"80000000-0000-4000-8000-000000012908","prompt":"Die Beschäftigten haben bei der Planung der Pausen ein Mitspracherecht. Was dürfen sie?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Having a say is not sole decision power.","de":"Mitreden bedeutet nicht, allein zu entscheiden."},"options":[{"id":"0","text":"Ihre Meinung in die Planung einbringen"},{"id":"1","text":"Alle Regeln allein und ohne Absprache festlegen"},{"id":"2","text":"Die Firma ohne Zustimmung verkaufen"},{"id":"3","text":"Jede Entscheidung der Leitung automatisch aufheben"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"They may contribute their views.","de":"Sie dürfen ihre Meinung bei der Planung äußern."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Beschäftigten können bei der Pausenplanung mitreden.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1579 (3b33052e144c4a3a831f1871a467e42bfa8a6c5ef031565d17a2bc9f547fb153), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
