INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001290141','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001290141","revision":1,"targetId":"80000000-0000-4000-8000-000000012914","prompt":"Die Stadt fördert Mobilität ohne eigenes Auto. Was soll erleichtert werden?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Think of travelling from place to place.","de":"Es geht um Wege von einem Ort zum anderen."},"options":[{"id":"0","text":"Die Fortbewegung mit anderen Verkehrsmitteln"},{"id":"1","text":"Die Berechnung der Einkommensteuer"},{"id":"2","text":"Die Herstellung von Büromöbeln"},{"id":"3","text":"Die Vergabe von Arbeitsverträgen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"People should be able to get around without cars.","de":"Die Fortbewegung ohne eigenes Auto soll einfacher werden."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Stadt erleichtert Wege ohne eigenes Auto.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1591 (0a0aedbee583c3cfa08e1ef96cac57880885a2b2394142221742c13dcd47a16e), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
