INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001290151','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001290151","revision":1,"targetId":"80000000-0000-4000-8000-000000012915","prompt":"Das Modell der Brücke steht im Museum und ist viel kleiner als das Original. Was ist es?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"It represents the original on a smaller scale.","de":"Es zeigt das Original in kleinerer Form."},"options":[{"id":"0","text":"Eine verkleinerte Darstellung der Brücke"},{"id":"1","text":"Eine Rechnung für den Brückenbau"},{"id":"2","text":"Ein amtliches Verkehrsschild"},{"id":"3","text":"Eine Liste der Bauarbeiter"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"It is a physical scale model.","de":"Es ist eine verkleinerte Darstellung der Brücke."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Museum steht ein verkleinertes Modell der Brücke.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1594 (cd8116524aab349d526ae244791cdc75a9b2cb76fbd00a236e7253f14e35ab4d), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
